// The calibrated 1836 economy generated by `npm run data:start` (scripts/build-start.ts).
import startJson from '../../data/start1836.json';
import type { GameState } from '../types';
import type { EconomyState } from './types';

const START = startJson as unknown as { economy: EconomyState };

/** Returns `state` with the pre-calibrated 1836 economy (a fresh copy). */
export function withStartEconomy(state: GameState): GameState {
  return { ...state, economy: structuredClone(START.economy) };
}
